'use strict';

// MAIN //

/**
* Returns defaults.
*
* @private
* @returns {Object} default options
*
* @example
* var o = defaults();
* // returns {...}
*/
function defaults() {
	return {
		// Horizontal text alignment:
		'align': 'left',

		// Rotation angle in degrees:
		'angle': 0,

		// Vertical text baseline:
		'baseline': 'alphabetic',

		// Text direction:
		'dir': 'ltr',

		// Ellipsis string for text truncation:
		'ellipsis': '\u2026',

		// Maximum length of the text mark in pixels (0 = no limit):
		'limit': 0,

		// Polar coordinate radial offset in pixels:
		'radius': 0,

		// Polar coordinate angle in radians:
		'theta': 0
	};
}


// EXPORTS //

module.exports = defaults;
